-- Verificar CARLOS HUMBERTO BUENO na inadimplência
SELECT cliente, LEFT(vencimentoData,10) as venc, valorLiquido, estado FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%CARLOS HUMBERTO%' AND estado = 'EMITIDO';

-- Verificar AMERICAN PIROTECNIA
SELECT cliente, LEFT(vencimentoData,10) as venc, valorLiquido, estado FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%AMERICAN%' AND estado = 'EMITIDO';

-- Verificar FAZENDA SANTA CRUZ
SELECT cliente, LEFT(vencimentoData,10) as venc, valorLiquido, estado FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%FAZENDA SANTA%' AND estado = 'EMITIDO';

